css:
/* 像素格：昼夜双版（:root 为日间基线，[data-reader-theme="night"] 覆盖夜景）；正文区占页高 80%+（蓝图硬约束①） */
:root{
  --pg-bg:#eef1f4; --pg-fg:#1d2733; --pg-dim:#5f6a78;
  --pg-accent:#1f6feb; --pg-pixel:rgba(31,111,235,.24);
}
[data-reader-theme="night"]{
  --pg-bg:#0b1120; --pg-fg:#e3ecff; --pg-dim:#8290a8;
  --pg-accent:#5b9bff; --pg-pixel:rgba(91,155,255,.26);
}
html,body{margin:0;padding:0;background:var(--pg-bg);color:var(--pg-fg);
  font-family:"JetBrains Mono","DejaVu Sans Mono",Consolas,monospace;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.8);}
body::before{content:"";position:absolute;inset:.5em;pointer-events:none;
  background-image:linear-gradient(var(--pg-pixel) 2px,transparent 2px),linear-gradient(90deg,var(--pg-pixel) 2px,transparent 2px);
  background-size:100% 12px,12px 100%;opacity:.5;
  -webkit-mask-image:linear-gradient(180deg,#000,transparent 42%,transparent 58%,#000);mask-image:linear-gradient(180deg,#000,transparent 42%,transparent 58%,#000);}
.pg-head{position:relative;display:flex;justify-content:space-between;align-items:center;gap:.6em;
  margin:.75em 1.1em 0;padding:.42em .7em;font-size:.76em;color:var(--pg-fg);
  background:var(--pg-bg);border:2px solid var(--pg-accent);box-shadow:4px 4px 0 0 var(--pg-pixel);}
.pg-chapter{max-width:70%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.pg-chapter::before{content:"▸ ";color:var(--pg-accent);}
.pg-pct{color:var(--pg-accent);font-variant-numeric:tabular-nums;}
.pg-title{position:relative;padding:1.1em 1.35em .5em;}
.pg-title-main{display:inline-block;font-size:1.5em;font-weight:700;letter-spacing:.08em;
  padding:.1em .38em;background:var(--pg-accent);color:var(--pg-bg);box-shadow:4px 4px 0 0 var(--pg-pixel);}
.pg-title-sub{display:block;margin-top:.5em;font-size:.72em;letter-spacing:.5em;color:var(--pg-dim);}
.pg-body{position:relative;padding:.9em 1.35em 0;}
.pg-body .reader-chapter-title{margin:0 0 .7em;font-size:1.24em;font-weight:700;}
.pg-body .reader-paragraph{margin:0 0 .9em;}
.pg-body p{margin:0 0 .9em;}
.pg-body a{color:var(--pg-accent);text-decoration:none;border-bottom:2px solid var(--pg-pixel);}
.pg-body blockquote{margin:0 0 1em;padding:.5em .85em;border-left:4px solid var(--pg-accent);color:var(--pg-dim);
  background:var(--pg-pixel);}
.pg-body code{background:var(--pg-pixel);padding:.14em .36em;border-radius:0;}
.pg-body pre{background:var(--pg-pixel);padding:.8em;border-radius:0;overflow-x:auto;border:2px solid var(--pg-accent);}
.pg-body table{width:100%;border-collapse:collapse;}
.pg-body th,.pg-body td{border:2px solid var(--pg-pixel);padding:.32em .5em;}
.pg-foot{position:relative;display:flex;justify-content:space-between;align-items:center;gap:.8em;
  margin:.65em 1.1em .95em;padding:.38em .7em;font-size:.7em;color:var(--pg-dim);
  font-variant-numeric:tabular-nums;border-top:2px solid var(--pg-pixel);}
@media (prefers-reduced-motion:reduce){.pg-title-main{box-shadow:3px 3px 0 0 var(--pg-pixel);}}
